declare global {
  interface Window {
    /** Meta's own alias, set by the official snippet. Preserved for parity. */
    _fbq?: unknown
  }
}

/**
 * The Meta Pixel stub, as MODULE code instead of an inline <script>.
 *
 * WHY IT MOVED. This was the last application-owned inline script that actually
 * executes — every other inline block in the document is generated by Next or
 * React, except the JSON-LD data blocks, which are never executed. Moving it
 * into a bundled module makes the app's own executing-inline-script count zero,
 * which is the precondition for ever adopting a nonce-based `script-src`
 * (see the CSP nonce audit). It changes nothing about today's policy.
 *
 * WHAT IT IS. A byte-for-byte behavioural port of Meta's published snippet:
 * the same idempotence guard, the same queue, the same `_fbq` alias, the same
 * `loaded`/`version` markers. Nothing was "improved" — the queue in particular
 * is load-bearing, because `trackPixelEvent()` may fire before fbevents.js has
 * arrived and those calls must be replayed rather than dropped.
 *
 * WHAT IT NO LONGER DOES. The snippet also injected fbevents.js itself
 * (`t.src=v` + insertBefore). That injection is now `next/script` with the same
 * `afterInteractive` strategy and the same URL, so the script element is
 * external either way and `connect.facebook.net` stays covered by the existing
 * `script-src` allowlist. Load ORDER remains safe in both directions: if the
 * stub installs first the queue drains when fbevents.js loads; if fbevents.js
 * wins the race it defines `fbq` itself and the guard below steps aside.
 */

type FbqStub = {
  (...args: unknown[]): void
  callMethod?: (...args: unknown[]) => void
  queue: unknown[][]
  push: unknown
  loaded: boolean
  version: string
}

export function ensureFbq(): void {
  if (typeof window === 'undefined') return
  // Meta's `if (f.fbq) return` — never replace a live pixel.
  if (window.fbq) return

  const stub = function (...args: unknown[]) {
    if (stub.callMethod) stub.callMethod.apply(stub, args)
    else stub.queue.push(args)
  } as FbqStub

  stub.queue = []
  stub.push = stub
  stub.loaded = true
  stub.version = '2.0'

  window.fbq = stub as unknown as Window['fbq']
  if (!window._fbq) window._fbq = stub
}
